"use client"

/**
 * Clean-room company command menu. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, or assets were copied.
 * command-palette is the grouped command list. This one searches companies.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { companySearchText, crmInitials, type CrmCompany, type CrmStatusTone } from "@/lib/crm-companies"

export type CrmCommandAction = {
  id: string
  label: string
  keywords?: string
  shortcut?: string
}

export type CrmCommandMenuLabels = {
  label?: string
  description?: string
  placeholder?: string
  empty?: string
  companies?: string
  actions?: string
  results?: (count: number) => string
}

export type CrmCommandMenuProps = {
  companies: readonly CrmCompany[]
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  onSelectCompany?: (company: CrmCompany) => void
  actions?: readonly CrmCommandAction[]
  onSelectAction?: (action: CrmCommandAction) => void
  /** Listen for Cmd-K or Ctrl-K. Turn this off when the sidebar already does. */
  hotkey?: boolean
  formatValue?: (value: number) => string
  labels?: CrmCommandMenuLabels
  className?: string
}

const TONE_VARIANT: Record<CrmStatusTone, "default" | "secondary" | "outline" | "destructive"> = {
  emphasis: "default",
  neutral: "secondary",
  muted: "outline",
  danger: "destructive",
}

function useControllable(value: boolean | undefined, defaultValue: boolean, onChange?: (next: boolean) => void) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value ?? internal
  const set = React.useCallback(
    (next: boolean) => {
      if (value === undefined) setInternal(next)
      onChange?.(next)
    },
    [onChange, value],
  )
  return [current, set] as const
}

export function CrmCommandMenu({
  companies,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  onSelectCompany,
  actions = [],
  onSelectAction,
  hotkey = true,
  formatValue = (value) => new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(value),
  labels,
  className,
}: CrmCommandMenuProps) {
  const [open, setOpen] = useControllable(openProp, defaultOpen, onOpenChange)
  const [query, setQuery] = React.useState("")
  const copy = {
    label: labels?.label ?? "Search companies",
    description: labels?.description ?? "Find a company or run a command",
    placeholder: labels?.placeholder ?? "Search companies",
    empty: labels?.empty ?? "No matching companies",
    companies: labels?.companies ?? "Companies",
    actions: labels?.actions ?? "Actions",
  }
  const needle = query.trim().toLocaleLowerCase()
  const matches = React.useMemo(() => {
    const filtered = needle ? companies.filter((company) => companySearchText(company).includes(needle)) : companies
    return filtered.slice(0, 20)
  }, [companies, needle])

  React.useEffect(() => {
    if (!hotkey) return
    const onKey = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() !== "k" || !(event.metaKey || event.ctrlKey)) return
      event.preventDefault()
      setOpen(!open)
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [hotkey, open, setOpen])

  function changeOpen(next: boolean) {
    if (!next) setQuery("")
    setOpen(next)
  }

  return (
    <CommandDialog
      open={open}
      onOpenChange={changeOpen}
      title={copy.label}
      description={copy.description}
      className={cn("sm:max-w-lg", className)}
    >
      <Command shouldFilter={false} label={copy.label} data-slot="crm-command-menu">
        <CommandInput placeholder={copy.placeholder} value={query} onValueChange={setQuery} aria-label={copy.label} />
        <CommandList>
          <CommandEmpty>{copy.empty}</CommandEmpty>
          {actions.length > 0 ? (
            <CommandGroup heading={copy.actions}>
              {actions.map((action) => (
                <CommandItem
                  key={action.id}
                  value={action.id}
                  onSelect={() => {
                    onSelectAction?.(action)
                    changeOpen(false)
                  }}
                >
                  <span className="min-w-0 flex-1 truncate">{action.label}</span>
                  {action.shortcut ? <span className="text-xs text-muted-foreground">{action.shortcut}</span> : null}
                </CommandItem>
              ))}
            </CommandGroup>
          ) : null}
          {actions.length > 0 && matches.length > 0 ? <CommandSeparator /> : null}
          {matches.length > 0 ? (
            <CommandGroup heading={labels?.results?.(matches.length) ?? copy.companies}>
              <div className="sr-only" role="row">
                <span>Name</span>
                <span>Status</span>
                <span>Owner</span>
                <span>Pipeline</span>
              </div>
              {matches.map((company) => {
                const value = formatValue(company.pipelineValue)
                return (
                  <CommandItem
                    key={company.id}
                    value={company.id}
                    onSelect={() => {
                      onSelectCompany?.(company)
                      changeOpen(false)
                    }}
                  >
                    <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                      <span className="flex min-w-0 items-center gap-2">
                        <Avatar size="sm">
                          {company.logoUrl ? <AvatarImage src={company.logoUrl} alt="" /> : null}
                          <AvatarFallback>{crmInitials(company.name)}</AvatarFallback>
                        </Avatar>
                        <span className="min-w-0 truncate font-medium">{company.name}</span>
                        <Badge variant={TONE_VARIANT[company.statusTone ?? "neutral"]} className="ms-auto">
                          {company.statusLabel}
                        </Badge>
                      </span>
                      <span className="flex min-w-0 items-center gap-2 ps-8 text-xs text-muted-foreground">
                        <span className="min-w-0 truncate">{company.owner}</span>
                        <span className="ms-auto shrink-0 tabular-nums text-foreground">{value}</span>
                      </span>
                      <span className="sr-only">
                        {company.name}, {company.statusLabel}, {company.owner}, {value}
                      </span>
                    </span>
                  </CommandItem>
                )
              })}
            </CommandGroup>
          ) : null}
        </CommandList>
      </Command>
    </CommandDialog>
  )
}

/**
 * Clean-room sales CRM model. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, sample rows, or assets were copied.
 */

export type CrmStatusTone = "neutral" | "emphasis" | "muted" | "danger"

export type CrmCompany = {
  id: string
  name: string
  logoUrl?: string
  status: string
  statusLabel: string
  statusTone?: CrmStatusTone
  owner: string
  ownerId?: string
  pipelineValue: number
  /** 0–100. */
  score: number
  /** Oldest to newest. The table draws this as a sparkline. */
  activity: readonly number[]
  activityLabel: string
  industry?: string
  region?: string
  email?: string
  website?: string
  phone?: string
  notes?: string
  /** Oldest to newest. The detail panel draws this as a trend. */
  trend?: readonly { key: string; label: string; value: number }[]
  /** 0–100 health for the meter. Falls back to score. */
  health?: number
}

export type CrmNotice = {
  id: string
  title: string
  description?: string
  time: string
  dateTime?: string
  read?: boolean
  companyId?: string
}

export type CrmSortKey = "name" | "status" | "owner" | "pipeline" | "score" | "activity"

export type CrmSort = {
  key: CrmSortKey
  direction: "asc" | "desc"
}

export type CrmFacetSelection = Record<string, readonly string[]>

export type CrmCompanyQuery = {
  search?: string
  /** Status id, or the all-segment id. */
  segment?: string
  allSegment?: string
  facets?: CrmFacetSelection
}

export type CrmCsvLabels = {
  name: string
  status: string
  owner: string
  pipeline: string
  score: string
  activity: string
}

export type CrmCompanyDraft = {
  name: string
  status: string
  ownerId: string
  email: string
  website: string
  industry: string
  region: string
  pipelineValue: string
  notes: string
  logo?: { type: string; size: number } | null
}

export type CrmDraftIssue =
  | "name-required"
  | "status-required"
  | "owner-required"
  | "email-invalid"
  | "website-invalid"
  | "pipeline-invalid"
  | "logo-type"
  | "logo-size"

export const CRM_LOGO_TYPES = ["image/png", "image/jpeg", "image/webp", "image/gif"] as const
export const CRM_LOGO_MAX_BYTES = 2_000_000

export const EMPTY_COMPANY_DRAFT: CrmCompanyDraft = {
  name: "",
  status: "",
  ownerId: "",
  email: "",
  website: "",
  industry: "",
  region: "",
  pipelineValue: "",
  notes: "",
  logo: null,
}

export function crmInitials(name: string) {
  const parts = name.split(/\s+/).filter(Boolean).slice(0, 2)
  const letters = parts.map((part) => [...part][0] ?? "").join("")
  return letters.toLocaleUpperCase() || "?"
}

export function companyFacetValue(company: CrmCompany, facetId: string) {
  if (facetId === "owner") return company.ownerId ?? company.owner
  if (facetId === "industry") return company.industry ?? ""
  if (facetId === "region") return company.region ?? ""
  if (facetId === "status") return company.status
  return ""
}

export function companySearchText(company: CrmCompany) {
  return [company.name, company.owner, company.statusLabel, company.industry, company.region, company.email]
    .filter(Boolean)
    .join(" ")
    .toLocaleLowerCase()
}

export function facetSelectionCount(selection: CrmFacetSelection) {
  return Object.values(selection).reduce((sum, values) => sum + values.length, 0)
}

export function toggleFacetValue(selection: CrmFacetSelection, facetId: string, value: string): CrmFacetSelection {
  const current = selection[facetId] ?? []
  const next = current.includes(value) ? current.filter((item) => item !== value) : [...current, value]
  return { ...selection, [facetId]: next }
}

export function filterCompanies(rows: readonly CrmCompany[], query: CrmCompanyQuery = {}) {
  const search = query.search?.trim().toLocaleLowerCase() ?? ""
  const allSegment = query.allSegment ?? "all"
  const segment = query.segment && query.segment !== allSegment ? query.segment : ""
  const facets = Object.entries(query.facets ?? {}).filter(([, values]) => values.length > 0)

  return rows.filter((company) => {
    if (segment && company.status !== segment) return false
    if (search && !companySearchText(company).includes(search)) return false
    return facets.every(([facetId, values]) => values.includes(companyFacetValue(company, facetId)))
  })
}

function sortValue(company: CrmCompany, key: CrmSortKey) {
  switch (key) {
    case "name":
      return company.name
    case "status":
      return company.statusLabel
    case "owner":
      return company.owner
    case "pipeline":
      return company.pipelineValue
    case "score":
      return company.score
    case "activity":
      return company.activity.at(-1) ?? 0
    default: {
      const unreachable: never = key
      return unreachable
    }
  }
}

export function sortCompanies(rows: readonly CrmCompany[], sort: CrmSort) {
  const direction = sort.direction === "asc" ? 1 : -1
  return [...rows].sort((a, b) => {
    const left = sortValue(a, sort.key)
    const right = sortValue(b, sort.key)
    const compared =
      typeof left === "number" && typeof right === "number"
        ? left - right
        : String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: "base" })
    if (compared !== 0) return compared * direction
    return a.id.localeCompare(b.id)
  })
}

export function paginate<T>(rows: readonly T[], page: number, pageSize: number) {
  const size = Math.max(1, Math.floor(pageSize) || 1)
  const total = rows.length
  const pages = Math.max(1, Math.ceil(total / size))
  const index = Math.min(Math.max(0, Math.floor(page) || 0), pages - 1)
  const start = index * size
  return {
    page: index,
    pages,
    start,
    end: Math.min(total, start + size),
    total,
    rows: rows.slice(start, start + size),
  }
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const WEBSITE = /^https?:\/\/\S+$/i

export function companyDraftIssues(draft: CrmCompanyDraft): CrmDraftIssue[] {
  const issues: CrmDraftIssue[] = []
  if (!draft.name.trim()) issues.push("name-required")
  if (!draft.status) issues.push("status-required")
  if (!draft.ownerId) issues.push("owner-required")
  if (draft.email.trim() && !EMAIL.test(draft.email.trim())) issues.push("email-invalid")
  if (draft.website.trim() && !WEBSITE.test(draft.website.trim())) issues.push("website-invalid")
  const pipeline = Number(draft.pipelineValue)
  if (draft.pipelineValue.trim() === "" || !Number.isFinite(pipeline) || pipeline < 0) issues.push("pipeline-invalid")
  if (draft.logo && draft.logo.size > 0) {
    if (!CRM_LOGO_TYPES.includes(draft.logo.type as (typeof CRM_LOGO_TYPES)[number])) issues.push("logo-type")
    if (draft.logo.size > CRM_LOGO_MAX_BYTES) issues.push("logo-size")
  }
  return issues
}

export function companyFromDraft(
  draft: CrmCompanyDraft & { logoUrl?: string },
  context: {
    id: string
    ownerName: string
    statusLabel: string
    statusTone?: CrmStatusTone
    activityLabel: string
  },
): CrmCompany {
  const pipelineValue = Number(draft.pipelineValue)
  return {
    id: context.id,
    name: draft.name.trim(),
    logoUrl: draft.logoUrl,
    status: draft.status,
    statusLabel: context.statusLabel,
    statusTone: context.statusTone,
    owner: context.ownerName,
    ownerId: draft.ownerId,
    pipelineValue: Number.isFinite(pipelineValue) ? pipelineValue : 0,
    score: 50,
    health: 50,
    activity: [2, 2, 3, 3],
    activityLabel: context.activityLabel,
    industry: draft.industry.trim() || undefined,
    region: draft.region.trim() || undefined,
    email: draft.email.trim() || undefined,
    website: draft.website.trim() || undefined,
    notes: draft.notes.trim() || undefined,
    trend: [{ key: "now", label: context.activityLabel, value: 1 }],
  }
}
